-- Speak sessions: 10 of them, N5.
--
-- Generated by `pnpm -C nihongo/backend seed:speak` from
-- backend/src/pipeline/data/speak. Do not edit: change the data and generate a
-- new seed. Audio was confirmed in the bucket when this was written.
--
-- Every session arrives UNPUBLISHED with a pending row in the admin review
-- queue. Approving it there is the only thing that publishes it.
--
-- Idempotent: nothing here overwrites an existing session, its steps, or a
-- review decision already made.

-- N5 · 1 · This is a book
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n5-01-desu', 'lang-ja', ll.id, 'n5-01-desu', 1, 'これは本です', 'This is a book', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-01-desu-s0', 'spk-ja-n5-01-desu', 0, 'explain', 'Welcome. We start with one tiny word. In English we say "is". In Japanese, "is" is {です}. It goes at the very end of the sentence.', NULL, NULL, NULL),
  ('spk-ja-n5-01-desu-s1', 'spk-ja-n5-01-desu', 1, 'explain', '"This" is {これ}. A book is {ほん}. After the thing you are talking about, put the little word you hear in {これは}. It marks the topic, a bit like "as for this".', NULL, NULL, NULL),
  ('spk-ja-n5-01-desu-s2', 'spk-ja-n5-01-desu', 2, 'prompt', 'How would you say "This is a book"?', 'これは本です。', 'これ わ ほん です。', NULL),
  ('spk-ja-n5-01-desu-s3', 'spk-ja-n5-01-desu', 3, 'explain', '"That", near you, is {それ}.', NULL, NULL, NULL),
  ('spk-ja-n5-01-desu-s4', 'spk-ja-n5-01-desu', 4, 'prompt', 'How would you say "That is a book"?', 'それは本です。', 'それ わ ほん です。', NULL),
  ('spk-ja-n5-01-desu-s5', 'spk-ja-n5-01-desu', 5, 'explain', 'Water is {みず}.', NULL, NULL, NULL),
  ('spk-ja-n5-01-desu-s6', 'spk-ja-n5-01-desu', 6, 'prompt', 'How would you say "This is water"?', 'これは水です。', 'これ わ みず です。', NULL),
  ('spk-ja-n5-01-desu-s7', 'spk-ja-n5-01-desu', 7, 'prompt', 'How would you say "That is water"?', 'それは水です。', 'それ わ みず です。', NULL),
  ('spk-ja-n5-01-desu-s8', 'spk-ja-n5-01-desu', 8, 'explain', 'To ask a question, put {か} at the end. Your voice goes up.', NULL, NULL, NULL),
  ('spk-ja-n5-01-desu-s9', 'spk-ja-n5-01-desu', 9, 'prompt', 'How would you say "Is this water?"', 'これは水ですか。', 'これ わ みず です か。', NULL),
  ('spk-ja-n5-01-desu-s10', 'spk-ja-n5-01-desu', 10, 'prompt', 'How would you say "Is that a book?"', 'それは本ですか。', 'それ わ ほん です か。', NULL),
  ('spk-ja-n5-01-desu-s11', 'spk-ja-n5-01-desu', 11, 'explain', 'Yes is {はい}.', NULL, NULL, NULL),
  ('spk-ja-n5-01-desu-s12', 'spk-ja-n5-01-desu', 12, 'prompt', 'How would you say "Yes, this is a book"?', 'はい、これは本です。', 'はい、これ わ ほん です。', NULL),
  ('spk-ja-n5-01-desu-s13', 'spk-ja-n5-01-desu', 13, 'explain', 'The word for "I" is {わたし}. A student is {がくせい}.', NULL, NULL, NULL),
  ('spk-ja-n5-01-desu-s14', 'spk-ja-n5-01-desu', 14, 'prompt', 'How would you say "I am a student"?', 'わたしは学生です。', 'わたし わ がくせい です。', NULL),
  ('spk-ja-n5-01-desu-s15', 'spk-ja-n5-01-desu', 15, 'explain', 'The word for "you" is {あなた}. Japanese uses it sparingly, but it is fine for now.', NULL, NULL, NULL),
  ('spk-ja-n5-01-desu-s16', 'spk-ja-n5-01-desu', 16, 'prompt', 'How would you say "Are you a student?"', 'あなたは学生ですか。', 'あなた わ がくせい です か。', NULL),
  ('spk-ja-n5-01-desu-s17', 'spk-ja-n5-01-desu', 17, 'explain', 'The little word {の} joins two things, like "my book" or "the teacher''s book". The first thing owns the second.', NULL, NULL, NULL),
  ('spk-ja-n5-01-desu-s18', 'spk-ja-n5-01-desu', 18, 'prompt', 'How would you say "This is my book"?', 'これはわたしの本です。', 'これ わ わたし の ほん です。', NULL),
  ('spk-ja-n5-01-desu-s19', 'spk-ja-n5-01-desu', 19, 'prompt', 'How would you say "Is that your book?"', 'それはあなたの本ですか。', 'それ わ あなた の ほん です か。', NULL),
  ('spk-ja-n5-01-desu-s20', 'spk-ja-n5-01-desu', 20, 'explain', 'A teacher is {せんせい}.', NULL, NULL, NULL),
  ('spk-ja-n5-01-desu-s21', 'spk-ja-n5-01-desu', 21, 'prompt', 'How would you say "I am a teacher"?', 'わたしは先生です。', 'わたし わ せんせい です。', NULL),
  ('spk-ja-n5-01-desu-s22', 'spk-ja-n5-01-desu', 22, 'prompt', 'How would you say "That is the teacher''s book"?', 'それは先生の本です。', 'それ わ せんせい の ほん です。', NULL),
  ('spk-ja-n5-01-desu-s23', 'spk-ja-n5-01-desu', 23, 'prompt', 'How would you say "Is this the teacher''s book?"', 'これは先生の本ですか。', 'これ わ せんせい の ほん です か。', NULL),
  ('spk-ja-n5-01-desu-s24', 'spk-ja-n5-01-desu', 24, 'explain', '{も} means "too". It goes where the topic word went: {わたしも}.', NULL, NULL, NULL),
  ('spk-ja-n5-01-desu-s25', 'spk-ja-n5-01-desu', 25, 'prompt', 'How would you say "I am a student too"?', 'わたしも学生です。', 'わたし も がくせい です。', NULL),
  ('spk-ja-n5-01-desu-s26', 'spk-ja-n5-01-desu', 26, 'prompt', 'How would you say "Is the teacher a student too?"', '先生も学生ですか。', 'せんせい も がくせい です か。', NULL),
  ('spk-ja-n5-01-desu-s27', 'spk-ja-n5-01-desu', 27, 'prompt', 'How would you say "This is my book too"?', 'これもわたしの本です。', 'これ も わたし の ほん です。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n5-01-desu')
ON CONFLICT (session_id, index) DO NOTHING;

