-- N5 · 2 · I eat, I drink
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n5-02-masu', 'lang-ja', ll.id, 'n5-02-masu', 2, '食べます', 'I eat, I drink', false
