SELECT v.* FROM (VALUES
  ('spk-ja-n5-02-masu-s0', 'spk-ja-n5-02-masu', 0, 'explain', 'Now actions. Polite Japanese verbs end in {ます}. "Eat" is {たべます}.', NULL, NULL, NULL),
  ('spk-ja-n5-02-masu-s1', 'spk-ja-n5-02-masu', 1, 'prompt', 'How would you say "I eat"?', '食べます。', 'たべます。', 'Japanese drops "I" when it is obvious.'),
  ('spk-ja-n5-02-masu-s2', 'spk-ja-n5-02-masu', 2, 'explain', 'Sushi is {すし}. The little word {を} marks the thing the action is done to. Listen: {すしを}.', NULL, NULL, NULL),
  ('spk-ja-n5-02-masu-s3', 'spk-ja-n5-02-masu', 3, 'prompt', 'How would you say "I eat sushi"?', 'すしを食べます。', 'すし お たべます。', NULL),
  ('spk-ja-n5-02-masu-s4', 'spk-ja-n5-02-masu', 4, 'explain', 'Rice, or a meal, is {ごはん}.', NULL, NULL, NULL),
  ('spk-ja-n5-02-masu-s5', 'spk-ja-n5-02-masu', 5, 'prompt', 'How would you say "I eat rice"?', 'ごはんを食べます。', 'ごはん お たべます。', NULL),
  ('spk-ja-n5-02-masu-s6', 'spk-ja-n5-02-masu', 6, 'explain', '"Drink" is {のみます}.', NULL, NULL, NULL),
  ('spk-ja-n5-02-masu-s7', 'spk-ja-n5-02-masu', 7, 'prompt', 'How would you say "I drink water"?', '水を飲みます。', 'みず お のみます。', NULL),
  ('spk-ja-n5-02-masu-s8', 'spk-ja-n5-02-masu', 8, 'explain', 'Tea is {おちゃ}.', NULL, NULL, NULL),
  ('spk-ja-n5-02-masu-s9', 'spk-ja-n5-02-masu', 9, 'prompt', 'How would you say "I drink tea"?', 'おちゃを飲みます。', 'おちゃ お のみます。', NULL),
  ('spk-ja-n5-02-masu-s10', 'spk-ja-n5-02-masu', 10, 'explain', '"Watch" or "see" is {みます}. Television is {テレビ}.', NULL, NULL, NULL),
  ('spk-ja-n5-02-masu-s11', 'spk-ja-n5-02-masu', 11, 'prompt', 'How would you say "I watch TV"?', 'テレビを見ます。', 'テレビ お みます。', NULL),
  ('spk-ja-n5-02-masu-s12', 'spk-ja-n5-02-masu', 12, 'explain', 'You know {か} already. Put it at the end for a question.', NULL, NULL, NULL),
  ('spk-ja-n5-02-masu-s13', 'spk-ja-n5-02-masu', 13, 'prompt', 'How would you say "Do you eat sushi?"', 'すしを食べますか。', 'すし お たべます か。', NULL),
  ('spk-ja-n5-02-masu-s14', 'spk-ja-n5-02-masu', 14, 'prompt', 'How would you say "Do you drink tea?"', 'おちゃを飲みますか。', 'おちゃ お のみます か。', NULL),
  ('spk-ja-n5-02-masu-s15', 'spk-ja-n5-02-masu', 15, 'prompt', 'How would you say "Do you watch TV?"', 'テレビを見ますか。', 'テレビ お みます か。', NULL),
  ('spk-ja-n5-02-masu-s16', 'spk-ja-n5-02-masu', 16, 'prompt', 'How would you say "Yes, I eat sushi"?', 'はい、すしを食べます。', 'はい、すし お たべます。', NULL),
  ('spk-ja-n5-02-masu-s17', 'spk-ja-n5-02-masu', 17, 'explain', '"Read" is {よみます}.', NULL, NULL, NULL),
  ('spk-ja-n5-02-masu-s18', 'spk-ja-n5-02-masu', 18, 'prompt', 'How would you say "I read a book"?', '本を読みます。', 'ほん お よみます。', NULL),
  ('spk-ja-n5-02-masu-s19', 'spk-ja-n5-02-masu', 19, 'prompt', 'How would you say "Do you read books?"', '本を読みますか。', 'ほん お よみます か。', NULL),
  ('spk-ja-n5-02-masu-s20', 'spk-ja-n5-02-masu', 20, 'prompt', 'How would you say "I read the teacher''s book"?', '先生の本を読みます。', 'せんせい の ほん お よみます。', NULL),
  ('spk-ja-n5-02-masu-s21', 'spk-ja-n5-02-masu', 21, 'explain', '"Every day" is {まいにち}. Put it near the start.', NULL, NULL, NULL),
  ('spk-ja-n5-02-masu-s22', 'spk-ja-n5-02-masu', 22, 'prompt', 'How would you say "I read a book every day"?', '毎日、本を読みます。', 'まいにち、ほん お よみます。', NULL),
  ('spk-ja-n5-02-masu-s23', 'spk-ja-n5-02-masu', 23, 'prompt', 'How would you say "I watch TV every day"?', '毎日、テレビを見ます。', 'まいにち、テレビ お みます。', NULL),
  ('spk-ja-n5-02-masu-s24', 'spk-ja-n5-02-masu', 24, 'prompt', 'How would you say "Do you eat rice every day?"', '毎日、ごはんを食べますか。', 'まいにち、ごはん お たべます か。', NULL),
  ('spk-ja-n5-02-masu-s25', 'spk-ja-n5-02-masu', 25, 'prompt', 'How would you say "Yes, I drink tea every day"?', 'はい、毎日、おちゃを飲みます。', 'はい、まいにち、おちゃ お のみます。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
