  ('spk-ja-n5-03-masen-s5', 'spk-ja-n5-03-masen', 5, 'prompt', 'How would you say "I don''t read books"?', '本を読みません。', 'ほん お よみません。', NULL),
  ('spk-ja-n5-03-masen-s6', 'spk-ja-n5-03-masen', 6, 'prompt', 'How would you say "Do you eat sushi?"', 'すしを食べますか。', 'すし お たべます か。', NULL),
  ('spk-ja-n5-03-masen-s7', 'spk-ja-n5-03-masen', 7, 'explain', 'No is {いいえ}.', NULL, NULL, NULL),
  ('spk-ja-n5-03-masen-s8', 'spk-ja-n5-03-masen', 8, 'prompt', 'How would you say "No, I don''t eat sushi"?', 'いいえ、すしを食べません。', 'いいえ、すし お たべません。', NULL),
  ('spk-ja-n5-03-masen-s9', 'spk-ja-n5-03-masen', 9, 'prompt', 'How would you say "Do you drink tea?"', 'おちゃを飲みますか。', 'おちゃ お のみます か。', NULL),
  ('spk-ja-n5-03-masen-s10', 'spk-ja-n5-03-masen', 10, 'prompt', 'How would you say "No, I don''t drink tea"?', 'いいえ、おちゃを飲みません。', 'いいえ、おちゃ お のみません。', NULL),
  ('spk-ja-n5-03-masen-s11', 'spk-ja-n5-03-masen', 11, 'explain', '"Not at all" is {ぜんぜん}. It goes just before the "not" verb.', NULL, NULL, NULL),
  ('spk-ja-n5-03-masen-s12', 'spk-ja-n5-03-masen', 12, 'prompt', 'How would you say "I don''t watch TV at all"?', 'テレビをぜんぜん見ません。', 'テレビ お ぜんぜん みません。', NULL),
  ('spk-ja-n5-03-masen-s13', 'spk-ja-n5-03-masen', 13, 'prompt', 'How would you say "I don''t read books at all"?', '本をぜんぜん読みません。', 'ほん お ぜんぜん よみません。', NULL),
  ('spk-ja-n5-03-masen-s14', 'spk-ja-n5-03-masen', 14, 'prompt', 'How would you say "No, I don''t eat rice"?', 'いいえ、ごはんを食べません。', 'いいえ、ごはん お たべません。', NULL),
  ('spk-ja-n5-03-masen-s15', 'spk-ja-n5-03-masen', 15, 'explain', 'That was for verbs. For "is not" with a noun, you say {じゃありません}, in place of {です}.', NULL, NULL, NULL),
  ('spk-ja-n5-03-masen-s16', 'spk-ja-n5-03-masen', 16, 'prompt', 'How would you say "This is not a book"?', 'これは本じゃありません。', 'これ わ ほん じゃ ありません。', NULL),
