INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-04-mashita-s0', 'spk-ja-n5-04-mashita', 0, 'explain', 'Now the past. {ます} becomes {ました}. "I ate" is {たべました}.', NULL, NULL, NULL),
  ('spk-ja-n5-04-mashita-s1', 'spk-ja-n5-04-mashita', 1, 'prompt', 'How would you say "I ate"?', '食べました。', 'たべました。', NULL),
  ('spk-ja-n5-04-mashita-s2', 'spk-ja-n5-04-mashita', 2, 'prompt', 'How would you say "I ate sushi"?', 'すしを食べました。', 'すし お たべました。', NULL),
  ('spk-ja-n5-04-mashita-s3', 'spk-ja-n5-04-mashita', 3, 'prompt', 'How would you say "I drank tea"?', 'おちゃを飲みました。', 'おちゃ お のみました。', NULL),
  ('spk-ja-n5-04-mashita-s4', 'spk-ja-n5-04-mashita', 4, 'prompt', 'How would you say "I watched TV"?', 'テレビを見ました。', 'テレビ お みました。', NULL),
  ('spk-ja-n5-04-mashita-s5', 'spk-ja-n5-04-mashita', 5, 'prompt', 'Now in the past. How would you say "I read a book", meaning it is done?', '本を読みました。', 'ほん お よみました。', NULL),
  ('spk-ja-n5-04-mashita-s6', 'spk-ja-n5-04-mashita', 6, 'prompt', 'How would you say "Did you eat sushi?"', 'すしを食べましたか。', 'すし お たべました か。', NULL),
  ('spk-ja-n5-04-mashita-s7', 'spk-ja-n5-04-mashita', 7, 'explain', 'And when you did not? Take {ません} and add {でした}. {ませんでした}.', NULL, NULL, NULL),
