  ('spk-ja-n5-04-mashita-s13', 'spk-ja-n5-04-mashita', 13, 'explain', 'Yesterday is {きのう}. Say it first.', NULL, NULL, NULL),
  ('spk-ja-n5-04-mashita-s14', 'spk-ja-n5-04-mashita', 14, 'prompt', 'How would you say "I ate sushi yesterday"?', 'きのう、すしを食べました。', 'きのう、すし お たべました。', NULL),
