  ('spk-ja-n5-04-mashita-s19', 'spk-ja-n5-04-mashita', 19, 'prompt', 'How would you say "I read a book today"?', '今日、本を読みました。', 'きょう、ほん お よみました。', NULL),
  ('spk-ja-n5-04-mashita-s20', 'spk-ja-n5-04-mashita', 20, 'prompt', 'How would you say "Did you watch TV today?"', '今日、テレビを見ましたか。', 'きょう、テレビ お みました か。', NULL),
