INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-05-tai-s0', 'spk-ja-n5-05-tai', 0, 'explain', 'To say what you want to do, take {ます} off the verb and add {たいです}. Eat is {たべます}. "Want to eat" is {たべたいです}.', NULL, NULL, NULL),
  ('spk-ja-n5-05-tai-s1', 'spk-ja-n5-05-tai', 1, 'prompt', 'How would you say "I want to eat"?', '食べたいです。', 'たべたい です。', NULL),
