  ('spk-ja-n5-05-tai-s3', 'spk-ja-n5-05-tai', 3, 'prompt', 'How would you say "I want to drink tea"?', 'おちゃを飲みたいです。', 'おちゃ お のみたい です。', NULL),
  ('spk-ja-n5-05-tai-s4', 'spk-ja-n5-05-tai', 4, 'prompt', 'How would you say "I want to watch TV"?', 'テレビを見たいです。', 'テレビ お みたい です。', NULL),
  ('spk-ja-n5-05-tai-s5', 'spk-ja-n5-05-tai', 5, 'prompt', 'How would you say "I want to read a book"?', '本を読みたいです。', 'ほん お よみたい です。', NULL),
  ('spk-ja-n5-05-tai-s6', 'spk-ja-n5-05-tai', 6, 'prompt', 'How would you say "Do you want to eat sushi?"', 'すしを食べたいですか。', 'すし お たべたい です か。', 'Fine with friends. To invite someone politely, there is a better way, coming soon.'),
  ('spk-ja-n5-05-tai-s7', 'spk-ja-n5-05-tai', 7, 'prompt', 'How would you say "Yes, I want to eat sushi"?', 'はい、すしを食べたいです。', 'はい、すし お たべたい です。', NULL),
  ('spk-ja-n5-05-tai-s8', 'spk-ja-n5-05-tai', 8, 'prompt', 'How would you say "Do you want to drink water?"', '水を飲みたいですか。', 'みず お のみたい です か。', NULL),
  ('spk-ja-n5-05-tai-s9', 'spk-ja-n5-05-tai', 9, 'explain', 'Now is {いま}. Say it first.', NULL, NULL, NULL),
  ('spk-ja-n5-05-tai-s10', 'spk-ja-n5-05-tai', 10, 'prompt', 'How would you say "I want to eat sushi now"?', '今、すしを食べたいです。', 'いま、すし お たべたい です。', NULL),
  ('spk-ja-n5-05-tai-s11', 'spk-ja-n5-05-tai', 11, 'prompt', 'How would you say "I want to drink tea now"?', '今、おちゃを飲みたいです。', 'いま、おちゃ お のみたい です。', NULL),
  ('spk-ja-n5-05-tai-s12', 'spk-ja-n5-05-tai', 12, 'prompt', 'How would you say "I want to watch TV today"?', '今日、テレビを見たいです。', 'きょう、テレビ お みたい です。', NULL),
  ('spk-ja-n5-05-tai-s13', 'spk-ja-n5-05-tai', 13, 'explain', 'Tomorrow is {あした}.', NULL, NULL, NULL),
  ('spk-ja-n5-05-tai-s14', 'spk-ja-n5-05-tai', 14, 'prompt', 'How would you say "I want to eat sushi tomorrow"?', 'あした、すしを食べたいです。', 'あした、すし お たべたい です。', NULL),
  ('spk-ja-n5-05-tai-s15', 'spk-ja-n5-05-tai', 15, 'prompt', 'How would you say "I want to read a book tomorrow"?', 'あした、本を読みたいです。', 'あした、ほん お よみたい です。', NULL),
  ('spk-ja-n5-05-tai-s16', 'spk-ja-n5-05-tai', 16, 'prompt', 'How would you say "Do you want to watch TV tomorrow?"', 'あした、テレビを見たいですか。', 'あした、テレビ お みたい です か。', NULL),
  ('spk-ja-n5-05-tai-s17', 'spk-ja-n5-05-tai', 17, 'explain', '"Go" is {いきます}. Take off {ます}, add {たいです}. {いきたいです}.', NULL, NULL, NULL),
  ('spk-ja-n5-05-tai-s18', 'spk-ja-n5-05-tai', 18, 'prompt', 'How would you say "I want to go"?', '行きたいです。', 'いきたい です。', NULL),
