-- N5 · 6 · Going and coming
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n5-06-places', 'lang-ja', ll.id, 'n5-06-places', 6, '行きます', 'Going and coming', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-06-places-s0', 'spk-ja-n5-06-places', 0, 'explain', 'You know {いきたいです}, "want to go". Put {ます} on the end instead, and you have {いきます}. "I go."', NULL, NULL, NULL),
  ('spk-ja-n5-06-places-s1', 'spk-ja-n5-06-places', 1, 'prompt', 'How would you say "I go"?', '行きます。', 'いきます。', NULL),
  ('spk-ja-n5-06-places-s2', 'spk-ja-n5-06-places', 2, 'explain', 'For the place you go to, use {に}. {がっこうに}. You can also use the little word you hear in {がっこうへ}. Both mean "to".', NULL, NULL, NULL),
  ('spk-ja-n5-06-places-s3', 'spk-ja-n5-06-places', 3, 'prompt', 'How would you say "I go to school"?', '学校に行きます。', 'がっこう に いきます。', NULL),
  ('spk-ja-n5-06-places-s4', 'spk-ja-n5-06-places', 4, 'prompt', 'Now with the other little word. How would you say "I am going to Japan"?', '日本へ行きます。', 'にほん え いきます。', 'に works just as well here.'),
  ('spk-ja-n5-06-places-s5', 'spk-ja-n5-06-places', 5, 'prompt', 'How would you say "Do you go to school?"', '学校に行きますか。', 'がっこう に いきます か。', NULL),
  ('spk-ja-n5-06-places-s6', 'spk-ja-n5-06-places', 6, 'prompt', 'How would you say "I don''t go to school"?', '学校に行きません。', 'がっこう に いきません。', NULL),
  ('spk-ja-n5-06-places-s7', 'spk-ja-n5-06-places', 7, 'prompt', 'How would you say "I went to school"?', '学校に行きました。', 'がっこう に いきました。', NULL),
  ('spk-ja-n5-06-places-s8', 'spk-ja-n5-06-places', 8, 'prompt', 'How would you say "I went to Japan yesterday"?', 'きのう、日本に行きました。', 'きのう、にほん に いきました。', NULL),
  ('spk-ja-n5-06-places-s9', 'spk-ja-n5-06-places', 9, 'explain', '"Come" is {きます}.', NULL, NULL, NULL),
  ('spk-ja-n5-06-places-s10', 'spk-ja-n5-06-places', 10, 'prompt', 'How would you say "I come"?', '来ます。', 'きます。', NULL),
  ('spk-ja-n5-06-places-s11', 'spk-ja-n5-06-places', 11, 'prompt', 'How would you say "I come to school"?', '学校に来ます。', 'がっこう に きます。', NULL),
  ('spk-ja-n5-06-places-s12', 'spk-ja-n5-06-places', 12, 'prompt', 'How would you say "I came to Japan"?', '日本に来ました。', 'にほん に きました。', NULL),
  ('spk-ja-n5-06-places-s13', 'spk-ja-n5-06-places', 13, 'prompt', 'How would you say "Do you come to school every day?"', '毎日、学校に来ますか。', 'まいにち、がっこう に きます か。', NULL),
  ('spk-ja-n5-06-places-s14', 'spk-ja-n5-06-places', 14, 'explain', '"Home" is {うち}. To go home, Japanese says "return": {かえります}.', NULL, NULL, NULL),
  ('spk-ja-n5-06-places-s15', 'spk-ja-n5-06-places', 15, 'prompt', 'How would you say "I go home"?', 'うちに帰ります。', 'うち に かえります。', NULL),
  ('spk-ja-n5-06-places-s16', 'spk-ja-n5-06-places', 16, 'prompt', 'How would you say "I went home yesterday"?', 'きのう、うちに帰りました。', 'きのう、うち に かえりました。', NULL),
  ('spk-ja-n5-06-places-s17', 'spk-ja-n5-06-places', 17, 'prompt', 'How would you say "I want to go home"?', 'うちに帰りたいです。', 'うち に かえりたい です。', NULL),
  ('spk-ja-n5-06-places-s18', 'spk-ja-n5-06-places', 18, 'explain', 'Now a different little word. For the place where something happens, use {で}. A restaurant is {レストラン}.', NULL, NULL, NULL),
  ('spk-ja-n5-06-places-s19', 'spk-ja-n5-06-places', 19, 'prompt', 'How would you say "I eat sushi at a restaurant"?', 'レストランですしを食べます。', 'レストラン で すし お たべます。', NULL),
  ('spk-ja-n5-06-places-s20', 'spk-ja-n5-06-places', 20, 'prompt', 'How would you say "I drank tea at home"?', 'うちでおちゃを飲みました。', 'うち で おちゃ お のみました。', NULL),
  ('spk-ja-n5-06-places-s21', 'spk-ja-n5-06-places', 21, 'prompt', 'How would you say "I read books at school every day"?', '毎日、学校で本を読みます。', 'まいにち、がっこう で ほん お よみます。', NULL),
  ('spk-ja-n5-06-places-s22', 'spk-ja-n5-06-places', 22, 'prompt', 'How would you say "I watch TV at home"?', 'うちでテレビを見ます。', 'うち で テレビ お みます。', NULL),
  ('spk-ja-n5-06-places-s23', 'spk-ja-n5-06-places', 23, 'prompt', 'How would you say "I go to the restaurant"?', 'レストランに行きます。', 'レストラン に いきます。', NULL),
  ('spk-ja-n5-06-places-s24', 'spk-ja-n5-06-places', 24, 'prompt', 'How would you say "I ate sushi at the restaurant yesterday"?', 'きのう、レストランですしを食べました。', 'きのう、レストラン で すし お たべました。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n5-06-places')
ON CONFLICT (session_id, index) DO NOTHING;

