INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-07-invite-s0', 'spk-ja-n5-07-invite', 0, 'explain', 'Remember {すし}, and {を} for the thing you eat. To invite someone, ask a "not" question. {ませんか} means "won''t you?", which is how you say "would you like to?". "Won''t you eat?" is {たべませんか}.', NULL, NULL, NULL),
  ('spk-ja-n5-07-invite-s1', 'spk-ja-n5-07-invite', 1, 'prompt', 'How would you say "Won''t you eat sushi?"', 'すしを食べませんか。', 'すし お たべません か。', NULL),
  ('spk-ja-n5-07-invite-s2', 'spk-ja-n5-07-invite', 2, 'prompt', 'How would you say "Won''t you drink tea?"', 'おちゃを飲みませんか。', 'おちゃ お のみません か。', NULL),
  ('spk-ja-n5-07-invite-s3', 'spk-ja-n5-07-invite', 3, 'prompt', 'How would you say "Won''t you go to the restaurant?"', 'レストランに行きませんか。', 'レストラン に いきません か。', NULL),
  ('spk-ja-n5-07-invite-s4', 'spk-ja-n5-07-invite', 4, 'explain', 'To say "let''s", change {ます} to {ましょう}. "Let''s eat" is {たべましょう}.', NULL, NULL, NULL),
  ('spk-ja-n5-07-invite-s5', 'spk-ja-n5-07-invite', 5, 'prompt', 'How would you say "Let''s eat sushi"?', 'すしを食べましょう。', 'すし お たべましょう。', NULL),
  ('spk-ja-n5-07-invite-s6', 'spk-ja-n5-07-invite', 6, 'prompt', 'How would you say "Let''s drink tea"?', 'おちゃを飲みましょう。', 'おちゃ お のみましょう。', NULL),
  ('spk-ja-n5-07-invite-s7', 'spk-ja-n5-07-invite', 7, 'prompt', 'How would you say "Let''s go to the restaurant"?', 'レストランに行きましょう。', 'レストラン に いきましょう。', NULL),
  ('spk-ja-n5-07-invite-s8', 'spk-ja-n5-07-invite', 8, 'prompt', 'How would you say "Let''s watch TV"?', 'テレビを見ましょう。', 'テレビ お みましょう。', NULL),
  ('spk-ja-n5-07-invite-s9', 'spk-ja-n5-07-invite', 9, 'prompt', 'How would you say "Let''s go home"?', 'うちに帰りましょう。', 'うち に かえりましょう。', NULL),
  ('spk-ja-n5-07-invite-s10', 'spk-ja-n5-07-invite', 10, 'prompt', 'How would you say "Let''s read a book"?', '本を読みましょう。', 'ほん お よみましょう。', NULL),
  ('spk-ja-n5-07-invite-s11', 'spk-ja-n5-07-invite', 11, 'explain', '"Together" is {いっしょに}.', NULL, NULL, NULL),
  ('spk-ja-n5-07-invite-s12', 'spk-ja-n5-07-invite', 12, 'prompt', 'How would you say "Won''t you eat sushi together?"', 'いっしょにすしを食べませんか。', 'いっしょ に すし お たべません か。', NULL),
  ('spk-ja-n5-07-invite-s13', 'spk-ja-n5-07-invite', 13, 'prompt', 'How would you say "Let''s go to the restaurant together"?', 'いっしょにレストランに行きましょう。', 'いっしょ に レストラン に いきましょう。', NULL),
  ('spk-ja-n5-07-invite-s14', 'spk-ja-n5-07-invite', 14, 'prompt', 'How would you say "Won''t you watch TV together?"', 'いっしょにテレビを見ませんか。', 'いっしょ に テレビ お みません か。', NULL),
  ('spk-ja-n5-07-invite-s15', 'spk-ja-n5-07-invite', 15, 'prompt', 'How would you say "Won''t you go to the restaurant tomorrow?"', 'あした、レストランに行きませんか。', 'あした、レストラン に いきません か。', NULL),
  ('spk-ja-n5-07-invite-s16', 'spk-ja-n5-07-invite', 16, 'prompt', 'How would you say "Yes, let''s go"?', 'はい、行きましょう。', 'はい、いきましょう。', NULL),
  ('spk-ja-n5-07-invite-s17', 'spk-ja-n5-07-invite', 17, 'prompt', 'How would you say "Yes, let''s eat sushi at the restaurant"?', 'はい、レストランですしを食べましょう。', 'はい、レストラン で すし お たべましょう。', NULL),
  ('spk-ja-n5-07-invite-s18', 'spk-ja-n5-07-invite', 18, 'explain', '"Excuse me" or "sorry" is {すみません}.', NULL, NULL, NULL),
  ('spk-ja-n5-07-invite-s19', 'spk-ja-n5-07-invite', 19, 'prompt', 'How would you say "Sorry, I am going home tomorrow"?', 'すみません、あした、うちに帰ります。', 'すみません、あした、うち に かえります。', NULL),
  ('spk-ja-n5-07-invite-s20', 'spk-ja-n5-07-invite', 20, 'explain', 'And {きます} is "come". Remember {わたしの}, "my".', NULL, NULL, NULL),
  ('spk-ja-n5-07-invite-s21', 'spk-ja-n5-07-invite', 21, 'prompt', 'How would you say "Won''t you come to my home?"', 'わたしのうちに来ませんか。', 'わたし の うち に きません か。', NULL),
  ('spk-ja-n5-07-invite-s22', 'spk-ja-n5-07-invite', 22, 'explain', 'To say yes, Japanese says "I go", because you are going from where you are. {はい、いきます}.', NULL, NULL, NULL),
  ('spk-ja-n5-07-invite-s23', 'spk-ja-n5-07-invite', 23, 'prompt', 'How would you say "Yes, I will come"?', 'はい、行きます。', 'はい、いきます。', NULL),
  ('spk-ja-n5-07-invite-s24', 'spk-ja-n5-07-invite', 24, 'prompt', 'How would you say "Let''s read a book together at school"?', 'いっしょに学校で本を読みましょう。', 'いっしょ に がっこう で ほん お よみましょう。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n5-07-invite')
ON CONFLICT (session_id, index) DO NOTHING;

