-- N5 · 8 · Please do it
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n5-08-kudasai', 'lang-ja', ll.id, 'n5-08-kudasai', 8, '見てください', 'Please do it', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-08-kudasai-s0', 'spk-ja-n5-08-kudasai', 0, 'explain', 'To ask someone to do something, change the end of the verb, then add {ください}, which means "please". Take {たべます}. Drop {ます}, add {て}. That gives {たべて}. "Please eat" is {たべてください}.', NULL, NULL, NULL),
  ('spk-ja-n5-08-kudasai-s1', 'spk-ja-n5-08-kudasai', 1, 'prompt', 'How would you say "Please eat"?', '食べてください。', 'たべて ください。', NULL),
  ('spk-ja-n5-08-kudasai-s2', 'spk-ja-n5-08-kudasai', 2, 'prompt', 'How would you say "Please eat sushi"?', 'すしを食べてください。', 'すし お たべて ください。', NULL),
  ('spk-ja-n5-08-kudasai-s3', 'spk-ja-n5-08-kudasai', 3, 'explain', '{みます} works the same way. {みて}, {みてください}. The thing you look at takes {を}: {これを}.', NULL, NULL, NULL),
  ('spk-ja-n5-08-kudasai-s4', 'spk-ja-n5-08-kudasai', 4, 'prompt', 'How would you say "Please look at this"?', 'これを見てください。', 'これ お みて ください。', NULL),
  ('spk-ja-n5-08-kudasai-s5', 'spk-ja-n5-08-kudasai', 5, 'prompt', 'How would you say "Please look at that"?', 'それを見てください。', 'それ お みて ください。', NULL),
  ('spk-ja-n5-08-kudasai-s6', 'spk-ja-n5-08-kudasai', 6, 'explain', '{よみます} and {のみます} change differently. {よみます} becomes {よんで}. Then {よんでください}. Notice it is {で}, not {て}. {みます}, to see, stays {みて}.', NULL, NULL, NULL),
  ('spk-ja-n5-08-kudasai-s7', 'spk-ja-n5-08-kudasai', 7, 'prompt', 'How would you say "Please read this"?', 'これを読んでください。', 'これ お よんで ください。', NULL),
  ('spk-ja-n5-08-kudasai-s8', 'spk-ja-n5-08-kudasai', 8, 'explain', 'Remember {せんせいのほん}, the teacher''s book.', NULL, NULL, NULL),
  ('spk-ja-n5-08-kudasai-s9', 'spk-ja-n5-08-kudasai', 9, 'prompt', 'How would you say "Please read the teacher''s book"?', '先生の本を読んでください。', 'せんせい の ほん お よんで ください。', NULL),
  ('spk-ja-n5-08-kudasai-s10', 'spk-ja-n5-08-kudasai', 10, 'explain', '{のみます} does the same. {のんで}.', NULL, NULL, NULL),
  ('spk-ja-n5-08-kudasai-s11', 'spk-ja-n5-08-kudasai', 11, 'prompt', 'How would you say "Please drink water"?', '水を飲んでください。', 'みず お のんで ください。', NULL),
  ('spk-ja-n5-08-kudasai-s12', 'spk-ja-n5-08-kudasai', 12, 'prompt', 'How would you say "Please drink tea"?', 'おちゃを飲んでください。', 'おちゃ お のんで ください。', NULL),
  ('spk-ja-n5-08-kudasai-s13', 'spk-ja-n5-08-kudasai', 13, 'explain', '{きます}, "come", becomes {きて}.', NULL, NULL, NULL),
  ('spk-ja-n5-08-kudasai-s14', 'spk-ja-n5-08-kudasai', 14, 'prompt', 'How would you say "Please come"?', '来てください。', 'きて ください。', NULL),
  ('spk-ja-n5-08-kudasai-s15', 'spk-ja-n5-08-kudasai', 15, 'prompt', 'How would you say "Please come to school"?', '学校に来てください。', 'がっこう に きて ください。', NULL),
  ('spk-ja-n5-08-kudasai-s16', 'spk-ja-n5-08-kudasai', 16, 'prompt', 'How would you say "Please come to my home"?', 'わたしのうちに来てください。', 'わたし の うち に きて ください。', NULL),
  ('spk-ja-n5-08-kudasai-s17', 'spk-ja-n5-08-kudasai', 17, 'prompt', 'How would you say "Please come tomorrow"?', 'あした来てください。', 'あした きて ください。', NULL),
  ('spk-ja-n5-08-kudasai-s18', 'spk-ja-n5-08-kudasai', 18, 'explain', '{いきます} becomes {いって}. {かえります} becomes {かえって}. Hear the little pause in the middle.', NULL, NULL, NULL),
  ('spk-ja-n5-08-kudasai-s19', 'spk-ja-n5-08-kudasai', 19, 'prompt', 'How would you say "Please go to the restaurant"?', 'レストランに行ってください。', 'レストラン に いって ください。', NULL),
  ('spk-ja-n5-08-kudasai-s20', 'spk-ja-n5-08-kudasai', 20, 'prompt', 'How would you say "Please go home"?', 'うちに帰ってください。', 'うち に かえって ください。', NULL),
  ('spk-ja-n5-08-kudasai-s21', 'spk-ja-n5-08-kudasai', 21, 'explain', '"Write" is {かきます}. It becomes {かいて}. "Name" is {なまえ}.', NULL, NULL, NULL),
  ('spk-ja-n5-08-kudasai-s22', 'spk-ja-n5-08-kudasai', 22, 'prompt', 'How would you say "Please write this"?', 'これを書いてください。', 'これ お かいて ください。', NULL),
  ('spk-ja-n5-08-kudasai-s23', 'spk-ja-n5-08-kudasai', 23, 'prompt', 'How would you say "Please write your name"?', '名前を書いてください。', 'なまえ お かいて ください。', 'Japanese leaves "your" out. Naming the person would sound too direct.'),
  ('spk-ja-n5-08-kudasai-s24', 'spk-ja-n5-08-kudasai', 24, 'explain', '"Listen" is {ききます}. It becomes {きいて}. A talk is {はなし}.', NULL, NULL, NULL),
  ('spk-ja-n5-08-kudasai-s25', 'spk-ja-n5-08-kudasai', 25, 'prompt', 'How would you say "Please listen"?', '聞いてください。', 'きいて ください。', NULL),
  ('spk-ja-n5-08-kudasai-s26', 'spk-ja-n5-08-kudasai', 26, 'prompt', 'How would you say "Please listen to the teacher''s talk"?', '先生の話を聞いてください。', 'せんせい の はなし お きいて ください。', NULL),
  ('spk-ja-n5-08-kudasai-s27', 'spk-ja-n5-08-kudasai', 27, 'prompt', 'How would you say "Please come to school every day"?', '毎日、学校に来てください。', 'まいにち、がっこう に きて ください。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n5-08-kudasai')
ON CONFLICT (session_id, index) DO NOTHING;

INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, origin, priority, status)
SELECT 'crq-spk-ja-n5-08-kudasai', 'lang-ja', 'speak_sessions', 'spk-ja-n5-08-kudasai', 'create', '{"code":"n5-08-kudasai","level":"N5","number":8}'::jsonb, 'ai', 1008, 'pending'
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n5-08-kudasai' AND NOT published)
  AND NOT EXISTS (SELECT 1 FROM content_review_queue WHERE target_table = 'speak_sessions' AND target_id = 'spk-ja-n5-08-kudasai')
