-- N5 · 9 · It is big
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n5-09-adjectives', 'lang-ja', ll.id, 'n5-09-adjectives', 9, '大きいです', 'It is big', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-09-adjectives-s0', 'spk-ja-n5-09-adjectives', 0, 'explain', 'Now describing things. Many describing words end in {い}. "Big" is {おおきい}. Put {です} after it. {おおきいです}.', NULL, NULL, NULL),
  ('spk-ja-n5-09-adjectives-s1', 'spk-ja-n5-09-adjectives', 1, 'prompt', 'How would you say "It is big"?', '大きいです。', 'おおきい です。', NULL),
  ('spk-ja-n5-09-adjectives-s2', 'spk-ja-n5-09-adjectives', 2, 'prompt', 'How would you say "This is big"?', 'これは大きいです。', 'これ わ おおきい です。', NULL),
  ('spk-ja-n5-09-adjectives-s3', 'spk-ja-n5-09-adjectives', 3, 'explain', '"Small" is {ちいさい}.', NULL, NULL, NULL),
  ('spk-ja-n5-09-adjectives-s4', 'spk-ja-n5-09-adjectives', 4, 'prompt', 'How would you say "That is small"?', 'それは小さいです。', 'それ わ ちいさい です。', NULL),
  ('spk-ja-n5-09-adjectives-s5', 'spk-ja-n5-09-adjectives', 5, 'explain', 'To say "not big", drop the final {い} and add {くないです}. {おおきくないです}.', NULL, NULL, NULL),
  ('spk-ja-n5-09-adjectives-s6', 'spk-ja-n5-09-adjectives', 6, 'prompt', 'How would you say "This is not big"?', 'これは大きくないです。', 'これ わ おおきくない です。', NULL),
  ('spk-ja-n5-09-adjectives-s7', 'spk-ja-n5-09-adjectives', 7, 'prompt', 'How would you say "That is not small"?', 'それは小さくないです。', 'それ わ ちいさくない です。', NULL),
  ('spk-ja-n5-09-adjectives-s8', 'spk-ja-n5-09-adjectives', 8, 'prompt', 'How would you say "Is this big?"', 'これは大きいですか。', 'これ わ おおきい です か。', NULL),
  ('spk-ja-n5-09-adjectives-s9', 'spk-ja-n5-09-adjectives', 9, 'prompt', 'How would you say "No, it is not big"?', 'いいえ、大きくないです。', 'いいえ、おおきくない です。', NULL),
  ('spk-ja-n5-09-adjectives-s10', 'spk-ja-n5-09-adjectives', 10, 'explain', '"Delicious" is {おいしい}. It follows the same rule.', NULL, NULL, NULL),
  ('spk-ja-n5-09-adjectives-s11', 'spk-ja-n5-09-adjectives', 11, 'prompt', 'How would you say "The sushi is delicious"?', 'すしはおいしいです。', 'すし わ おいしい です。', NULL),
  ('spk-ja-n5-09-adjectives-s12', 'spk-ja-n5-09-adjectives', 12, 'prompt', 'How would you say "The tea is not delicious"?', 'おちゃはおいしくないです。', 'おちゃ わ おいしくない です。', NULL),
  ('spk-ja-n5-09-adjectives-s13', 'spk-ja-n5-09-adjectives', 13, 'prompt', 'How would you say "Is the sushi delicious?"', 'すしはおいしいですか。', 'すし わ おいしい です か。', NULL),
  ('spk-ja-n5-09-adjectives-s14', 'spk-ja-n5-09-adjectives', 14, 'explain', 'Put the describing word before the noun. {おおきいほん}, a big book.', NULL, NULL, NULL),
  ('spk-ja-n5-09-adjectives-s15', 'spk-ja-n5-09-adjectives', 15, 'prompt', 'How would you say "It is a big book"?', '大きい本です。', 'おおきい ほん です。', NULL),
  ('spk-ja-n5-09-adjectives-s16', 'spk-ja-n5-09-adjectives', 16, 'prompt', 'How would you say "This is a big book"?', 'これは大きい本です。', 'これ わ おおきい ほん です。', NULL),
  ('spk-ja-n5-09-adjectives-s17', 'spk-ja-n5-09-adjectives', 17, 'prompt', 'How would you say "That is not a big book"?', 'それは大きい本じゃありません。', 'それ わ おおきい ほん じゃ ありません。', NULL),
  ('spk-ja-n5-09-adjectives-s18', 'spk-ja-n5-09-adjectives', 18, 'prompt', 'How would you say "The sushi at the restaurant is delicious"?', 'レストランのすしはおいしいです。', 'レストラン の すし わ おいしい です。', NULL),
  ('spk-ja-n5-09-adjectives-s19', 'spk-ja-n5-09-adjectives', 19, 'explain', '"Expensive", or "high", is {たかい}.', NULL, NULL, NULL),
  ('spk-ja-n5-09-adjectives-s20', 'spk-ja-n5-09-adjectives', 20, 'prompt', 'How would you say "This is expensive"?', 'これは高いです。', 'これ わ たかい です。', NULL),
  ('spk-ja-n5-09-adjectives-s21', 'spk-ja-n5-09-adjectives', 21, 'prompt', 'How would you say "This is not expensive"?', 'これは高くないです。', 'これ わ たかくない です。', NULL),
  ('spk-ja-n5-09-adjectives-s22', 'spk-ja-n5-09-adjectives', 22, 'prompt', 'How would you say "Is the restaurant expensive?"', 'レストランは高いですか。', 'レストラン わ たかい です か。', NULL),
  ('spk-ja-n5-09-adjectives-s23', 'spk-ja-n5-09-adjectives', 23, 'explain', 'Some describing words do not end in {い}. "Quiet" is {しずか}. Just add {です}. To say "not", use {じゃありません}, as you did with nouns.', NULL, NULL, NULL),
  ('spk-ja-n5-09-adjectives-s24', 'spk-ja-n5-09-adjectives', 24, 'prompt', 'How would you say "The school is quiet"?', '学校はしずかです。', 'がっこう わ しずか です。', NULL),
  ('spk-ja-n5-09-adjectives-s25', 'spk-ja-n5-09-adjectives', 25, 'prompt', 'How would you say "The restaurant is not quiet"?', 'レストランはしずかじゃありません。', 'レストラン わ しずか じゃ ありません。', NULL),
  ('spk-ja-n5-09-adjectives-s26', 'spk-ja-n5-09-adjectives', 26, 'explain', '"Pretty", or "clean", is {きれい}. Careful. It ends in {い}, but it is one of the {しずか} kind. So "not pretty" is {きれいじゃありません}.', NULL, NULL, NULL),
  ('spk-ja-n5-09-adjectives-s27', 'spk-ja-n5-09-adjectives', 27, 'prompt', 'How would you say "Japan is pretty"?', '日本はきれいです。', 'にほん わ きれい です。', NULL),
  ('spk-ja-n5-09-adjectives-s28', 'spk-ja-n5-09-adjectives', 28, 'prompt', 'How would you say "The restaurant is not pretty"?', 'レストランはきれいじゃありません。', 'レストラン わ きれい じゃ ありません。', NULL),
  ('spk-ja-n5-09-adjectives-s29', 'spk-ja-n5-09-adjectives', 29, 'explain', 'Before a noun, these words take {な}. {しずかながっこう}.', NULL, NULL, NULL),
  ('spk-ja-n5-09-adjectives-s30', 'spk-ja-n5-09-adjectives', 30, 'prompt', 'How would you say "It is a quiet school"?', 'しずかな学校です。', 'しずかな がっこう です。', NULL),
  ('spk-ja-n5-09-adjectives-s31', 'spk-ja-n5-09-adjectives', 31, 'prompt', 'How would you say "It is a pretty restaurant"?', 'きれいなレストランです。', 'きれいな レストラン です。', NULL),
  ('spk-ja-n5-09-adjectives-s32', 'spk-ja-n5-09-adjectives', 32, 'prompt', 'How would you say "This is a quiet restaurant"?', 'これはしずかなレストランです。', 'これ わ しずかな レストラン です。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n5-09-adjectives')
ON CONFLICT (session_id, index) DO NOTHING;

