SELECT 'crq-spk-ja-n5-09-adjectives', 'lang-ja', 'speak_sessions', 'spk-ja-n5-09-adjectives', 'create', '{"code":"n5-09-adjectives","level":"N5","number":9}'::jsonb, 'ai', 1009, 'pending'
