-- N5 · 10 · Because
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n5-10-kara', 'lang-ja', ll.id, 'n5-10-kara', 10, 'おいしいですから', 'Because', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-10-kara-s0', 'spk-ja-n5-10-kara', 0, 'explain', 'Everything you know comes back today. Remember {すし}, {まいにち} and {たべます}. The last piece is "because". The little word {から} goes after the reason. "It is delicious, so I eat it every day" is the reason first, {おいしいですから}, then what follows.', NULL, NULL, NULL),
  ('spk-ja-n5-10-kara-s1', 'spk-ja-n5-10-kara', 1, 'prompt', 'How would you say "The sushi is delicious, so I eat it every day"?', 'すしはおいしいですから、毎日、食べます。', 'すし わ おいしい です から、まいにち、たべます。', NULL),
  ('spk-ja-n5-10-kara-s2', 'spk-ja-n5-10-kara', 2, 'prompt', 'How would you say "It is expensive, so I don''t eat it"?', '高いですから、食べません。', 'たかい です から、たべません。', NULL),
  ('spk-ja-n5-10-kara-s3', 'spk-ja-n5-10-kara', 3, 'prompt', 'How would you say "It is quiet, so I want to read a book"?', 'しずかですから、本を読みたいです。', 'しずか です から、ほん お よみたい です。', NULL),
  ('spk-ja-n5-10-kara-s4', 'spk-ja-n5-10-kara', 4, 'prompt', 'How would you say "The school is quiet, so I read books at school"?', '学校はしずかですから、学校で本を読みます。', 'がっこう わ しずか です から、がっこう で ほん お よみます。', NULL),
  ('spk-ja-n5-10-kara-s5', 'spk-ja-n5-10-kara', 5, 'explain', 'After a verb, use {ますから}. "I am going to the restaurant, so" is {レストランにいきますから}.', NULL, NULL, NULL),
